sys_script_include.script:
var UWFieldSnapshotDiff = Class.create();
UWFieldSnapshotDiff.prototype = {
    initialize: function() {},

    /**
     * Compare two plain-object snapshots and report which allow-listed fields
     * changed. Values are compared as strings so a number/boolean/GlideRecord
     * getValue() result and a hand-built string both compare consistently;
     * missing keys on either side are treated as ''.
     *
     * @param oldSnapshot plain object {fieldName: value}, e.g. {total_insured_value: '1000000'}
     * @param newSnapshot plain object {fieldName: value}, same shape as oldSnapshot
     * @param allowList array of field names to consider - fields outside this
     *        list are ignored even if they differ between the two snapshots
     * @return array of field names (subset of allowList) whose value differs
     */
    diff: function(oldSnapshot, newSnapshot, allowList) {
        oldSnapshot = oldSnapshot || {};
        newSnapshot = newSnapshot || {};
        allowList = allowList || [];

        var changed = [];
        for (var i = 0; i < allowList.length; i++) {
            var field = allowList[i];
            var oldValue = this._asString(oldSnapshot[field]);
            var newValue = this._asString(newSnapshot[field]);
            if (oldValue !== newValue)
                changed.push(field);
        }
        return changed;
    },

    /** true if diff() would report at least one changed allow-listed field. */
    hasChange: function(oldSnapshot, newSnapshot, allowList) {
        return this.diff(oldSnapshot, newSnapshot, allowList).length > 0;
    },

    _asString: function(value) {
        return (value === null || value === undefined) ? '' : String(value);
    },

    type: 'UWFieldSnapshotDiff'
};
